const countdownRenderer = ({minutes, seconds, driverName, driverPlate, props }: CountdownRenderProps & { driverName: string, driverPlate: string }) => {
    if (minutes === 0 && seconds === 0) {
        return <Text>{driverName} arrived</Text>;
    } else {
