func (s *Server) rideHistory(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	var (
		response interface{}
		err      error
	)
	switch r.Method {
	case http.MethodGet:
		response, err = s.location.ListRideHistory(ctx)
	case http.MethodPost:
		var ride location.RideHistory
		if err = json.NewDecoder(r.Body).Decode(&ride); err != nil {
			s.rideHistoryError(w, r, err, http.StatusBadRequest)
			return
		}
		response, err = s.location.CreateRideHistory(ctx, &ride)
	case http.MethodPatch:
		var update location.RideHistoryUpdate
		if err = json.NewDecoder(r.Body).Decode(&update); err != nil {
			s.rideHistoryError(w, r, err, http.StatusBadRequest)
			return
		}
		response, err = s.location.UpdateRideHistory(ctx, &update)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	if err != nil {
		status := http.StatusInternalServerError
		var httpErr *location.HTTPError
		if errors.As(err, &httpErr) {
			status = httpErr.StatusCode
		}
		s.rideHistoryError(w, r, err, status)
		return
	}
	s.writeResponse(response, w, r)
}

