import {useCallback, useEffect, useRef, useState} from "react";
import {apiGet, apiPatch, apiPost} from "../services/http.ts";
import {RideHistory, RideHistoryList} from "../types/rideHistory.ts";

type DriverAssignment = {
    plate: string,
    fare: number,
}

// Tracks, per request, the ride history entry and the driver assignment. The
// driver notification can arrive before the entry creation has completed, so
// the PATCH is sent as soon as both are known, whichever comes last.
type PendingRide = {
    entryID?: number,
    assignment?: DriverAssignment,
}

export const useRideHistory = () => {
    const [rides, setRides] = useState<RideHistory[]>([]);
    const [total, setTotal] = useState(0);
    const pendingRef = useRef(new Map<number, PendingRide>());

    const refresh = useCallback(async () => {
        try {
            const list = await apiGet<RideHistoryList>('/ride-history');
            setRides(list.rides ?? []);
            setTotal(list.total ?? 0);
        } catch (e) {
            console.error('cannot load ride history', e);
        }
    }, []);

    useEffect(() => {
        refresh();
    }, [refresh]);

    const sendAssignment = useCallback(async (entryID: number, assignment: DriverAssignment) => {
        try {
            await apiPatch<RideHistory>('/ride-history', {
                id: entryID,
                driverPlate: assignment.plate,
                fare: assignment.fare,
            });
        } catch (e) {
            console.error('cannot update ride history', e);
        }
        await refresh();
    }, [refresh]);

    const addRide = useCallback(async (requestID: number, pickupName: string, dropoffName: string) => {
        const pending: PendingRide = pendingRef.current.get(requestID) ?? {};
        pendingRef.current.set(requestID, pending);
        try {
            const created = await apiPost<RideHistory>('/ride-history', {
                pickupName,
                dropoffName,
                requestTime: new Date().toISOString(),
            }, {});
            pending.entryID = created.id;
        } catch (e) {
            console.error('cannot create ride history entry', e);
            pendingRef.current.delete(requestID);
            return;
        }
        if (pending.assignment) {
            await sendAssignment(pending.entryID, pending.assignment);
            pendingRef.current.delete(requestID);
        } else {
            await refresh();
        }
    }, [refresh, sendAssignment]);

    const assignDriver = useCallback(async (requestID: number, assignment: DriverAssignment) => {
        const pending: PendingRide = pendingRef.current.get(requestID) ?? {};
        pendingRef.current.set(requestID, pending);
        if (pending.assignment) return; // already handled (e.g. notification redelivered)
        pending.assignment = assignment;
        if (pending.entryID !== undefined) {
            await sendAssignment(pending.entryID, assignment);
            pendingRef.current.delete(requestID);
        }
    }, [sendAssignment]);

    return {rides, total, addRide, assignDriver};
};
EOF
