		want float64
	}{
		{0, 3.50},
		{1 * time.Minute, 3.50},
		{2 * time.Minute, 3.50},
		{2*time.Minute + 20*time.Second, 3.50},
		{2*time.Minute + 30*time.Second, 3.75},
		{4 * time.Minute, 6.00},
		{10*time.Minute + 20*time.Second, 15.50},
	}
	for _, tt := range tests {
		if got := computeFare(tt.eta); got != tt.want {
			t.Errorf("computeFare(%v) = %v, want %v", tt.eta, got, tt.want)
		}
	}
}
EOF
